"""Check acceptance/rejection behavior of the two raw statistics consumers.

These tests exercise reporting gates, not the Java memo algorithm. The separate
Java contracts must establish the actual key, mutation, adaptation, and lifetime
behavior before timing is possible.
"""
import copy
import importlib.util
import json
from pathlib import Path
import sys
import tempfile
import unittest

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))


def load(name, file):
    spec = importlib.util.spec_from_file_location(name, HERE / file)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


DRIVER = load('direct_driver_tests', 'run-comparison.py')
ANALYSIS = load('direct_analysis_tests', 'analyze-timing-independent.py')


class QualificationConsumersTest(unittest.TestCase):

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.folder = Path(self.temporary.name)
        self.samples = [{'iteration': i - 8, 'stage': 'warmup' if i < 8 else 'measurement',
                         'ledgerPeakBytes': 10_000_000, 'counters': {'lazyValueCalls': 4000 + i}}
                        for i in range(13)]
        self.header = {'type': 'memoStatisticsMetadata', 'format': 1, 'scope': DRIVER.ACCOUNTING_SCOPE,
            'fixture': 'fanout', 'delegateLauncher': DRIVER.FIXTURES['fanout']['launcher'],
            'harnessReturned': True, 'harnessFailureClass': None, 'capacity': 13,
            'opened': 13, 'closed': 13, 'size': 13, 'overflowCount': 0}
        self.owners = []
        lazy = 0
        for i, sample in enumerate(self.samples):
            owner = {key: 0 for key in DRIVER.ACCOUNTING_FIELDS}
            owner.update({'type': 'owner', 'recordIndex': i, 'ownerOrdinal': i + 1,
                'compileOrdinalAtOpen': i + 1, 'compileOrdinalAtClose': i + 1,
                'lazyValueCallsAtOpen': lazy,
                'lazyValueCallsAtClose': lazy + sample['counters']['lazyValueCalls'],
                'probes': 10000, 'hits': 6000, 'collisions': 1000,
                'peakCapacity': 4096, 'peakArrayBytes': 147536,
                'retainedEntriesAtClose': 3000, 'capacityAtClose': 4096})
            self.owners.append(owner)
            lazy = owner['lazyValueCallsAtClose']

    def tearDown(self):
        self.temporary.cleanup()

    def consume(self, arm='direct', accepted=True):
        path = self.folder / 'direct-memo-statistics.jsonl'
        path.write_text('\n'.join(json.dumps(v) for v in [self.header, *self.owners]) + '\n')
        calls = [lambda: DRIVER.validate_accounting(self.folder, 'fanout', arm, self.samples),
                 lambda: ANALYSIS.read_accounting(self.folder, 'fanout', arm, self.samples)]
        for call in calls:
            if accepted:
                self.assertTrue(call()['qualified'])
            else:
                with self.assertRaises(ValueError):
                    call()

    def test_complete_direct_records_allow_varying_raw_resolver_counts(self):
        self.consume()

    def test_controls_require_no_direct_owner(self):
        self.owners = []
        self.header.update(opened=0, closed=0, size=0)
        self.consume('ordinary')
        self.consume('dense')

    def test_direct_owner_in_control_is_rejected(self):
        self.consume('ordinary', accepted=False)

    def test_valid_low_hit_disable_is_an_outcome(self):
        self.owners[0].update(probes=8192, hits=2000, collisions=5000, lowHitDisable=1,
                              disabledAtClose=1, capacityAtClose=0, retainedEntriesAtClose=0)
        self.consume()

    def test_disable_after_wrong_probe_boundary_is_rejected(self):
        self.owners[0].update(probes=9000, hits=2000, collisions=5000, lowHitDisable=1,
                              disabledAtClose=1, capacityAtClose=0, retainedEntriesAtClose=0)
        self.consume(accepted=False)

    def test_scope_clear_total_is_reported_without_a_zero_gate(self):
        self.owners[0]['clearCalls'] = 2
        self.consume()

    def test_probe_outcomes_cannot_exceed_probes(self):
        self.owners[0]['collisions'] = 4001
        self.consume(accepted=False)

    def test_mutation_or_unsupported_value_is_rejected(self):
        for field in ('invalidations', 'unsupportedValues'):
            with self.subTest(field=field):
                self.owners[0][field] = 1
                self.consume(accepted=False)
                self.owners[0][field] = 0

    def test_refusal_or_unreleased_charge_is_rejected(self):
        for field in ('initialAdmissionRefusals', 'growthAdmissionRefusals', 'arrayBytesAfterClose'):
            with self.subTest(field=field):
                self.owners[0][field] = 1
                self.consume(accepted=False)
                self.owners[0][field] = 0

    def test_resize_peak_includes_old_and_new_arrays(self):
        self.owners[0].update(resizes=1, peakCapacity=8192, capacityAtClose=8192,
                              peakArrayBytes=147536 + 294992, probes=16384, hits=8000, collisions=4000)
        self.consume()
        self.owners[0]['peakArrayBytes'] = 294992
        self.consume(accepted=False)

    def test_growth_cannot_precede_its_probe_boundary(self):
        self.owners[0].update(resizes=4, peakCapacity=65536, capacityAtClose=65536,
                              peakArrayBytes=3539104, probes=10000, hits=6000, collisions=1000)
        self.consume(accepted=False)

    def test_fixed_hash_doubling_cannot_discard_rehash_collisions(self):
        self.owners[0]['rehashDiscards'] = 1
        self.consume(accepted=False)

    def test_owner_query_compile_mismatch_is_rejected(self):
        self.owners[6]['compileOrdinalAtOpen'] = 6
        self.consume(accepted=False)

    def test_inter_owner_resolver_gap_is_rejected(self):
        self.owners[4]['lazyValueCallsAtOpen'] += 1
        self.owners[4]['lazyValueCallsAtClose'] += 1
        self.consume(accepted=False)

    def test_overflow_is_rejected(self):
        self.header['overflowCount'] = 1
        self.consume(accepted=False)

    def test_capacity_must_follow_successful_growth(self):
        self.owners[0]['peakCapacity'] = 8192
        self.consume(accepted=False)


class DesignScreenTest(unittest.TestCase):

    def comparison(self, comparator, fixture, latency):
        return {'fixture': fixture, 'numerator': 'direct', 'denominator': comparator,
                'perRound': [{'round': i, 'ratios': {'totalNs': value, 'allThreadAllocatedBytes': 0.9}}
                             for i, value in enumerate(latency)]}

    def results(self):
        return [self.comparison(comparator, fixture, [0.94] * 6)
                for comparator in ('ordinary', 'dense') for fixture in DRIVER.FIXTURE_ORDER]

    def test_balanced_orders_and_budget_are_fixed(self):
        self.assertEqual(ANALYSIS.ARMS, DRIVER.ARMS)
        self.assertEqual(ANALYSIS.ORDERS, DRIVER.ORDERS)
        self.assertEqual(ANALYSIS.OWNER_FIELDS, tuple(DRIVER.ACCOUNTING_FIELDS))
        for arm in DRIVER.ARMS:
            self.assertEqual([sum(order[position] == arm for order in DRIVER.ORDERS)
                              for position in range(3)], [2, 2, 2])
        self.assertEqual(6 * 2 * 3 * 13, 468)

    def test_separate_comparator_screens(self):
        comparisons = self.results()
        pairs = [{'passed': True}] * 312
        self.assertTrue(ANALYSIS.total_effect_screen(comparisons, pairs)['bothPassed'])
        changed = copy.deepcopy(comparisons)
        next(v for v in changed if v['fixture'] == 'fanout' and v['denominator'] == 'dense')['perRound'][0][
            'ratios']['totalNs'] = 1.01
        result = ANALYSIS.total_effect_screen(changed, pairs)
        self.assertTrue(next(v for v in result['screens'] if v['comparator'] == 'ordinary')['passed'])
        self.assertFalse(next(v for v in result['screens'] if v['comparator'] == 'dense')['passed'])


if __name__ == '__main__':
    unittest.main(verbosity=2)
